import typer
from rich.console import Console

from datum.floor import render_floor
from datum.rules_doctor import do_preflight
from datum.status_render import load_state, render
import json

app = typer.Typer(
    name="datum",
    help="DATUM V2 - Agentic Production Line Orchestrator",
    add_completion=False,
)
console = Console()


@app.command()
def floor():
    """Render the live Manager Factory Floor dashboard."""
    render_floor()


@app.command()
def doctor(
    phase: str = typer.Option("act", help="The current DATUM phase"),
    role: str = typer.Option("general", help="The agent's role"),
):
    """Run the Rules Doctor preflight evaluation."""
    do_preflight(phase, role)


@app.command()
def status(json_output: bool = typer.Option(False, "--json", help="Output raw JSON")):
    """Show the live pipeline status for the active run."""
    state = load_state()
    if json_output:
        console.print(json.dumps(state, indent=2))
    else:
        console.print(render(state))


@app.command()
def init():
    """Bootstrap the repository for DATUM execution."""
    from datum.state import ensure_feature_branch
    from datum.bootstrap import seed_state_docs
    import sys

    branch = ensure_feature_branch()
    console.print(f"[dim]Branch: {branch}[/dim]")
    console.print("[bold green]Bootstrapping DATUM...[/bold green]")
    try:
        seed_state_docs.main()
        console.print("[bold green]✓ Repo seeded.[/bold green]")
    except Exception as e:
        console.print(f"[bold red]Bootstrap failed: {e}[/bold red]")
        sys.exit(1)


@app.command()
def migrate(
    dry_run: bool = typer.Option(
        False, "--dry-run", help="Simulate migration without making changes"
    )
):
    """Migrate legacy .wfc repositories to .datum and upgrade schemas."""
    import sys
    from datum.migrate import (
        migrate_wfc_directory,
        load_state,
        migrate_state,
        current_skill_version,
        save_state,
    )

    console.print("[bold blue]Starting DATUM Migration...[/bold blue]")
    dir_changes = migrate_wfc_directory(dry_run)
    for c in dir_changes:
        console.print(f"[yellow]• {c}[/yellow]")

    state = load_state()
    if not state and not dir_changes:
        console.print(
            "[green]No legacy .wfc/ directory or .datum/state.json found. Nothing to do.[/green]"
        )
        return

    migrated, changes = migrate_state(state, current_skill_version())
    for c in changes:
        console.print(f"[yellow]• {c}[/yellow]")

    if not dry_run and state:
        save_state(migrated)

    try:
        from datum.contracts import validate_value

        errors = validate_value("state.schema.json", migrated) if migrated else []
    except Exception as exc:
        errors = [str(exc)]

    if errors:
        console.print(
            "[bold red]Migration completed with validation errors:[/bold red]"
        )
        for e in errors:
            console.print(f"  - {e}")
        sys.exit(1)

    if dry_run:
        console.print("[bold green]Dry run complete. No changes made.[/bold green]")
    else:
        console.print("[bold green]✓ Migration successful.[/bold green]")


@app.command()
def install(
    dry_run: bool = typer.Option(
        False, "--dry-run", help="Simulate installation without making changes"
    )
):
    """Install a stable snapshot of the DATUM skill globally for AI Agents."""
    import sys
    from datum.bootstrap.install_skill import install_skill_snapshot

    console.print("[bold blue]Installing DATUM Agent Skill globally...[/bold blue]")
    try:
        actions = install_skill_snapshot(dry_run)
        for action in actions:
            console.print(f"[yellow]• {action}[/yellow]")

        if dry_run:
            console.print("[bold green]Dry run complete. No changes made.[/bold green]")
        else:
            console.print(
                "[bold green]✓ DATUM skill successfully installed and linked across all agents![/bold green]"
            )
            console.print(
                "\n[dim]Your agents will use the self-contained 'uv run scripts/datum.py' execution wrapper. No global installation needed![/dim]"
            )
    except Exception as e:
        console.print(f"[bold red]Installation failed: {e}[/bold red]")
        sys.exit(1)


def main():
    """Main entrypoint for the uv-managed script."""
    app()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Gate validator for DATUM phases. Enforces completion criteria before phase transitions.

Usage:
  python3 scripts/gate.py <phase> [--yolo] [--skip-human]
  python3 scripts/gate.py validate-packets

Exit codes:
  0 — gate passed
  1 — gate failed (surfaceable issue, retry possible)
  2 — hard stop (never retried, never bypassed)
"""

import argparse
import json
import re
import sys
from pathlib import Path

# Fix relative imports
sys.path.insert(0, str(Path(__file__).parent))
from datum.contracts import validate_payload, validate_value
from datum.path_utils import assets_dir, templates_dir, existing_review_packets_dir


def load_config() -> dict:
    config_path = Path(".datum/config.toml")
    default_path = assets_dir() / "config.toml.default"

    for path in (config_path, default_path):
        if path.exists():
            try:
                import tomllib  # type: ignore[import]
            except ImportError:
                try:
                    import tomli as tomllib  # type: ignore[import]
                except ImportError:
                    return {}
            with path.open("rb") as f:
                return tomllib.load(f)
    return {}


def gate_policy(config: dict, gate_name: str) -> str:
    return config.get("gates", {}).get(gate_name, "skippable_if_complete")


def fail(message: str, hard: bool = False) -> None:
    print(json.dumps({"passed": False, "hard_stop": hard, "message": message}))
    sys.exit(2 if hard else 1)


def pass_gate(message: str = "gate passed") -> None:
    print(json.dumps({"passed": True, "message": message}))
    sys.exit(0)


# ── Phase gate implementations ──────────────────────────────────────────────


def gate_refine(yolo: bool, config: dict) -> None:
    spec = Path("SPEC.md")
    if not spec.exists():
        fail("SPEC.md not found")

    content = spec.read_text()

    required_sections = [
        "Summary",
        "Requirements",
        "Failure modes",
        "Non-functional",
        "Out of scope",
    ]
    missing = [s for s in required_sections if s.lower() not in content.lower()]
    if missing:
        fail(f"SPEC.md missing sections: {missing}")

    # Check for open questions
    if re.search(r"open question", content, re.IGNORECASE):
        if "[ ]" in content or "TBD" in content or "TODO" in content:
            fail("SPEC.md has unresolved open questions or TODOs")

    policy = gate_policy(config, "refine_human_review")
    if policy == "required" and not yolo:
        print(
            json.dumps(
                {
                    "passed": False,
                    "needs_human": True,
                    "message": "SPEC.md ready for human review. Approve to continue.",
                    "artifact": "SPEC.md",
                }
            )
        )
        sys.exit(1)

    pass_gate("Refine gate passed")


def gate_plan(yolo: bool, config: dict) -> None:
    tasks_path = Path("TASKS.md")
    lane_plan_path = Path(".datum/lane-plan.json")

    if not tasks_path.exists():
        fail("TASKS.md not found")
    if not lane_plan_path.exists():
        fail("Missing .datum/lane-plan.json. Run lane_plan.py first.")

    # Validate lane-plan.json structure
    with lane_plan_path.open() as f:
        lane_plan = json.load(f)

    schema_errors = validate_payload("lane-plan.schema.json", lane_plan_path)
    if schema_errors:
        fail(f"lane-plan.json schema validation failed: {schema_errors}", hard=True)

    lanes = lane_plan.get("lanes", {})
    lane_ids = set(lanes)
    topological_order = lane_plan.get("topological_order", [])
    if set(topological_order) != lane_ids:
        fail("lane-plan.json topological_order does not match lanes")

    file_to_lanes: dict[str, list[str]] = {}
    for lid, lane in lanes.items():
        if "files" not in lane:
            fail(f"Lane {lid} missing 'files' field in lane-plan.json")
        if "red_note" not in lane:
            fail(f"Lane {lid} missing 'red_note' in lane-plan.json")
        if "task_complexity" not in lane:
            print(
                f"⚠️ Warning: Lane {lid} lacks explicit task_complexity. Defaulting to 'behavioral'.",
                file=sys.stderr,
            )
        if "acceptance_criteria" not in lane or not lane["acceptance_criteria"]:
            fail(f"Lane {lid} missing acceptance_criteria")
        for dep in lane.get("depends_on", []):
            if dep not in lane_ids:
                fail(f"Lane {lid} depends on unknown lane {dep}")
        for f in lane.get("files", []):
            file_to_lanes.setdefault(f, []).append(lid)

    for f, owners in file_to_lanes.items():
        if len(owners) < 2:
            continue
        for owner in owners:
            deps = set(lanes[owner].get("depends_on", []))
            others = set(owners) - {owner}
            if not (deps & others):
                fail(
                    f"File overlap {f} across {sorted(owners)} has no dependency edge for {owner}"
                )

    # Plan approval is always required (never skippable)
    policy = gate_policy(config, "plan_human_approval")
    if policy != "skipped":
        print(
            json.dumps(
                {
                    "passed": False,
                    "needs_human": True,
                    "message": "TASKS.md and lane-plan.json ready for human approval.",
                    "artifacts": ["TASKS.md", ".datum/lane-plan.json"],
                }
            )
        )
        sys.exit(1)

    pass_gate("Plan gate passed")


def gate_triage(yolo: bool, config: dict) -> None:
    routing_path = Path(".datum/routing.json")
    if not routing_path.exists():
        fail(
            "routing.json not found. Triage subagent must write decision to .datum/routing.json"
        )

    with routing_path.open() as f:
        routing = json.load(f)

    if routing.get("decision") not in ("deepen", "properties"):
        fail("Invalid routing decision. Must be 'deepen' or 'properties'.")

    pass_gate("Triage gate passed")


def gate_deepen(yolo: bool, config: dict) -> None:
    tasks_path = Path("TASKS.md")
    if not tasks_path.exists():
        fail("TASKS.md not found")

    content = tasks_path.read_text()
    if "## Research Findings" not in content and "## Research" not in content:
        fail(
            "TASKS.md missing '## Research Findings' section. Deepen phase must append evidence."
        )

    pass_gate("Deepen gate passed")


def gate_properties(yolo: bool, config: dict) -> None:
    props_path = Path("PROPERTIES.md")
    if not props_path.exists():
        fail("PROPERTIES.md not found")

    content = props_path.read_text()

    required_categories = [
        "SAFETY",
        "LIVENESS",
        "INVARIANT",
        "BOUNDARY",
        "IDEMPOTENT",
        "ORDERING",
        "ISOLATION",
        "PERFORMANCE",
        "SECURITY",
        "OBSERVABILITY",
        "COMPATIBILITY",
    ]
    missing = [c for c in required_categories if c not in content]
    if missing:
        fail(f"PROPERTIES.md missing categories: {missing}")

    # Check traceability table exists
    if "task-" not in content.lower() and "task_" not in content.lower():
        fail("PROPERTIES.md missing traceability table (no task references found)")

    policy = gate_policy(config, "properties_human_review")
    if policy == "required" and not yolo:
        print(
            json.dumps(
                {
                    "passed": False,
                    "needs_human": True,
                    "message": "PROPERTIES.md ready for human review.",
                    "artifact": "PROPERTIES.md",
                }
            )
        )
        sys.exit(1)

    pass_gate("Properties gate passed")


def gate_validate(yolo: bool, config: dict) -> None:
    # Check test signal from most recent run
    signal_path = Path(".datum/last-test-signal.json")
    if signal_path.exists():
        with signal_path.open() as f:
            signal = json.load(f)
        if signal.get("status") not in ("pass",):
            fail(f"Test suite not green: {signal.get('status')}")

    policy = gate_policy(config, "validate_human_review")
    if policy == "required" and not yolo:
        print(
            json.dumps(
                {
                    "passed": False,
                    "needs_human": True,
                    "message": "Validation results ready for review.",
                }
            )
        )
        sys.exit(1)

    pass_gate("Validate gate passed")


def gate_review(yolo: bool, config: dict) -> None:
    report_path = Path("REVIEW-REPORT.md")
    packets_dir = existing_review_packets_dir()

    if not report_path.exists():
        fail("REVIEW-REPORT.md not found")
    if not packets_dir.exists():
        fail(f"review-packets/ directory not found: {packets_dir}")

    # Check for high-severity findings
    content = report_path.read_text() if report_path.exists() else ""
    if (
        "severity: high" in content.lower()
        or "**high**" in content.lower()
        or "severity: critical" in content.lower()
        or "**critical**" in content.lower()
    ):
        # Satisfaction Loop Logic
        state_path = Path(".datum/state.json")
        run_id = "default"
        if state_path.exists():
            import json

            run_id = json.loads(state_path.read_text()).get("run_id", "default")

        iter_file = Path(f".datum/runs/{run_id}/.review-iteration")
        iteration = 1
        if iter_file.exists():
            iteration = int(iter_file.read_text().strip())

        if iteration >= 3:
            fail(
                "REVIEW-REPORT.md contains HIGH/CRITICAL findings after 3 iterations. "
                "ESCALATION TO CHIEF OF STAFF: Architectural review required before proceeding.",
                hard=True,
            )
        else:
            import subprocess

            print(
                f"Gate review failed (Iteration {iteration}/3). Generating Remediation Package..."
            )
            subprocess.run(
                [
                    "python3",
                    "scripts/remediate.py",
                    "--run-id",
                    run_id,
                    "--findings",
                    f".datum/runs/{run_id}/review-packets/unified.json",
                ]
            )
            iter_file.parent.mkdir(parents=True, exist_ok=True)
            iter_file.write_text(str(iteration + 1))
            fail(
                f"REVIEW-REPORT.md contains high-severity findings — Remediation Package generated for Iteration {iteration}. Fix and retry."
            )

    pass_gate("Review gate passed")


def gate_pr_comments(yolo: bool, config: dict) -> None:
    triage_path = Path(".datum/triage.json")
    if not triage_path.exists():
        fail("triage.json not found")

    with triage_path.open() as f:
        triage = json.load(f)

    unresolved = [
        item
        for item in triage.get("items", [])
        if item.get("verdict") == "discuss" and not item.get("replied")
    ]
    if unresolved:
        fail(f"{len(unresolved)} PR comment threads still pending discussion")

    policy = gate_policy(config, "triage_human_approval")
    if policy == "required" and not yolo:
        print(
            json.dumps(
                {
                    "passed": False,
                    "needs_human": True,
                    "message": "Triage results ready for human approval.",
                    "artifact": ".datum/triage.json",
                }
            )
        )
        sys.exit(1)

    pass_gate("PR Comments gate passed")


def gate_validate_packets(config: dict) -> None:
    packets_dir = existing_review_packets_dir()
    if not packets_dir.exists():
        fail(f"review-packets/ not found: {packets_dir}")

    errors = []
    for packet_path in packets_dir.glob("*.json"):
        packet_errors = validate_payload("packet.schema.json", packet_path)
        errors.extend(f"{packet_path.name}: {err}" for err in packet_errors)

    if errors:
        fail(f"Packet validation errors: {errors}")

    pass_gate("Packets valid")


def _load_yaml_profile(path: Path) -> dict:
    try:
        import yaml  # type: ignore[import-not-found]
    except ImportError:
        fail("PyYAML is required for validate-profiles")

    with path.open() as f:
        data = yaml.safe_load(f) or {}
    if not isinstance(data, dict):
        fail(f"{path} is not a YAML object")
    return data


def _profile_path(name: str) -> Path:
    repo_path = Path(".datum/profiles") / name
    if repo_path.exists():
        return repo_path
    return templates_dir() / name


def gate_validate_profiles(config: dict) -> None:
    profile_pairs = [
        ("quality.yaml", assets_dir() / "schemas/quality.schema.json"),
        ("environment.yaml", assets_dir() / "schemas/environment.schema.json"),
    ]

    errors = []
    for profile_name, schema_path in profile_pairs:
        profile_path = _profile_path(profile_name)
        if not profile_path.exists():
            errors.append(f"{profile_name}: missing profile and template")
            continue
        data = _load_yaml_profile(profile_path)
        profile_errors = validate_value(schema_path, data)
        errors.extend(f"{profile_path}: {err}" for err in profile_errors)

    if errors:
        fail(f"Profile validation errors: {errors}", hard=True)

    pass_gate("Profiles valid")


# ── Dispatch ─────────────────────────────────────────────────────────────────


GATES = {
    "refine": gate_refine,
    "plan": gate_plan,
    "triage": gate_triage,
    "deepen": gate_deepen,
    "properties": gate_properties,
    "validate": gate_validate,
    "review": gate_review,
    "pr-comments": gate_pr_comments,
}


def main() -> None:
    from datum.state import ensure_feature_branch

    ensure_feature_branch()

    parser = argparse.ArgumentParser(description="DATUM gate validator")
    parser.add_argument("phase")
    parser.add_argument("--yolo", action="store_true")
    parser.add_argument("--skip-human", action="store_true")
    args = parser.parse_args()

    config = load_config()

    if args.phase == "validate-packets":
        gate_validate_packets(config)
        return
    if args.phase == "validate-profiles":
        gate_validate_profiles(config)
        return

    if args.phase not in GATES:
        print(json.dumps({"error": f"unknown gate: {args.phase}"}))
        sys.exit(1)

    GATES[args.phase](args.yolo or args.skip_human, config)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Builds lane-plan.json and TASKS.md from tasks.json.

Usage:
  python3 scripts/lane_plan.py [--validate] [--input tasks.json] [--output .datum/lane-plan.json]
"""

import argparse
import json
import sys
from pathlib import Path


def validate_json_schema(data: list, schema_path: Path):
    """Validate data against JSON schema if jsonschema is available."""
    try:
        import jsonschema
        with schema_path.open() as f:
            schema = json.load(f)
        # Handle relative $ref in items
        if "items" in schema and "$ref" in schema["items"]:
            # This is a bit simplified, but works for our repo structure
            ref_path = schema_path.parent / schema["items"]["$ref"]
            with ref_path.open() as f:
                ref_schema = json.load(f)
            schema["items"] = ref_schema

        jsonschema.validate(instance=data, schema=schema)
        return True, []
    except ImportError:
        # Fallback to basic validation if jsonschema not installed
        errors = []
        for i, task in enumerate(data):
            for field in ["id", "title", "acceptance_criteria", "files", "red_note"]:
                if field not in task:
                    errors.append(f"Task {i} ({task.get('id', 'unknown')}): missing {field}")
        return len(errors) == 0, errors
    except Exception as e:
        return False, [str(e)]


def build_file_ownership(tasks: list[dict]) -> tuple[dict[str, str], dict[str, list[str]]]:
    """Map each file to its owning lane. Detect conflicts."""
    ownership: dict[str, str] = {}
    conflicts: dict[str, list[str]] = {}

    for task in tasks:
        for f in task["files"]:
            if f in ownership:
                conflicts.setdefault(f, [ownership[f]]).append(task["id"])
            else:
                ownership[f] = task["id"]

    return ownership, conflicts


def topological_sort(tasks: list[dict]) -> list[str]:
    """Return task IDs in topological order. Raises on cycle."""
    id_set = {t["id"] for t in tasks}
    deps = {t["id"]: [d for d in t.get("depends_on", []) if d in id_set] for t in tasks}

    visited: set[str] = set()
    temp: set[str] = set()
    order: list[str] = []

    def visit(node: str) -> None:
        if node in temp:
            raise ValueError(f"Circular dependency detected involving: {node}")
        if node in visited:
            return
        temp.add(node)
        for dep in deps.get(node, []):
            visit(dep)
        temp.discard(node)
        visited.add(node)
        order.append(node)

    for task in tasks:
        if task["id"] not in visited:
            visit(task["id"])

    return order


def render_tasks_md(tasks: list[dict], sorted_ids: list[str]) -> str:
    """Render a human-readable TASKS.md from the task list."""
    task_map = {t["id"]: t for t in tasks}
    lines = ["# Implementation Plan (TASKS.md)", ""]

    lines.append("## Dependency Graph")
    lines.append("```mermaid")
    lines.append("graph TD")
    for tid in sorted_ids:
        task = task_map[tid]
        for dep in task.get("depends_on", []):
            lines.append(f"  {dep} --> {tid}")
    lines.append("```")
    lines.append("")

    for tid in sorted_ids:
        task = task_map[tid]
        lines.append(f"## {task['id']}: {task['title']}")
        if task.get("description"):
            lines.append(f"{task['description']}")
            lines.append("")

        lines.append("- **Acceptance Criteria**:")
        for ac in task["acceptance_criteria"]:
            lines.append(f"  - {ac}")

        lines.append(f"- **Files**: {', '.join(task['files'])}")

        if task.get("depends_on"):
            lines.append(f"- **Depends on**: {', '.join(task['depends_on'])}")

        lines.append(f"- **RED Note**: {task['red_note']}")

        if task.get("introduces_stubs"):
            lines.append("- **Introduces Stubs**: true")

        if task.get("estimated_loc"):
            lines.append(f"- **Estimated LOC**: {task['estimated_loc']}")

        lines.append("")

    return "\n".join(lines)


def build_lane_plan(tasks: list[dict], sorted_ids: list[str], ownership: dict) -> dict:
    """Build the full lane-plan.json structure."""
    task_map = {t["id"]: t for t in tasks}

    lanes = {}
    for tid in sorted_ids:
        task = task_map[tid]

        # Determine file-ownership conflicts (write-write conflicts with other lanes)
        write_conflicts = {}
        for f in task["files"]:
            owner = ownership.get(f)
            if owner and owner != tid:
                write_conflicts[f] = owner

        lanes[tid] = {
            "id": tid,
            "title": task["title"],
            "files": task["files"],
            "acceptance_criteria": task["acceptance_criteria"],
            "red_note": task["red_note"],
            "introduces_stubs": task.get("introduces_stubs", False),
            "estimated_loc": task.get("estimated_loc", 0),
            "depends_on": task.get("depends_on", []),
            "file_conflict_with": write_conflicts,
            "stage": "queued",
        }

    return {
        "schema_version": "1.0.0",
        "total_lanes": len(lanes),
        "topological_order": sorted_ids,
        "file_ownership": ownership,
        "lanes": lanes,
    }


def main() -> None:
    parser = argparse.ArgumentParser(description="Build lane-plan.json and TASKS.md from tasks.json")
    parser.add_argument("--validate", action="store_true")
    parser.add_argument("--input", default="tasks.json")
    parser.add_argument("--output", default=".datum/lane-plan.json")
    parser.add_argument("--md-output", default="TASKS.md")
    args = parser.parse_args()

    input_path = Path(args.input)
    if not input_path.exists():
        print(json.dumps({"error": f"{args.input} not found"}))
        sys.exit(1)

    try:
        tasks = json.loads(input_path.read_text())
    except json.JSONDecodeError as e:
        print(json.dumps({"error": f"Failed to parse {args.input}: {str(e)}"}))
        sys.exit(1)

    sys.path.insert(0, str(Path(__file__).parent))
    from path_utils import assets_dir
    schema_path = assets_dir() / "schemas/tasks.schema.json"
    valid, errors = validate_json_schema(tasks, schema_path)

    if not valid:
        print(json.dumps({"error": "Schema validation failed", "details": errors}))
        sys.exit(1)

    if args.validate:
        try:
            topological_sort(tasks)
            print(json.dumps({"valid": True, "task_count": len(tasks)}))
        except ValueError as e:
            print(json.dumps({"valid": False, "error": str(e)}))
            sys.exit(1)
        return

    try:
        sorted_ids = topological_sort(tasks)
    except ValueError as e:
        print(json.dumps({"error": str(e)}))
        sys.exit(1)

    ownership, _ = build_file_ownership(tasks)
    lane_plan = build_lane_plan(tasks, sorted_ids, ownership)

    # Write lane-plan.json
    out_path = Path(args.output)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with out_path.open("w") as f:
        json.dump(lane_plan, f, indent=2)

    # Write TASKS.md
    md_content = render_tasks_md(tasks, sorted_ids)
    Path(args.md_output).write_text(md_content)

    print(
        json.dumps(
            {
                "ok": True,
                "lane_plan": args.output,
                "tasks_md": args.md_output,
                "total_lanes": lane_plan["total_lanes"],
            }
        )
    )


