import os
import re
from collections import defaultdict

def extract_predicates(content):
    predicates = []

    # 1. Traceability tables: | ID | Category | Predicate | ... |
    # or | ID | Predicate | ... |
    lines = content.split('\n')
    for line in lines:
        if '|' in line and re.search(r'[A-Z]{3,5}-\d+', line):
            parts = [p.strip() for p in line.split('|')]
            # Usually: '', ID, Category, Predicate, ...
            if len(parts) >= 4:
                # If ID is parts[1], Predicate is often parts[3] or parts[2]
                if re.match(r'[A-Z]{3,5}-\d+', parts[1]):
                    # Check if parts[2] is a category (SAFETY, etc)
                    categories = ['SAFETY', 'LIVENESS', 'INVARIANT', 'BOUNDARY', 'IDEMPOTENT', 'ORDERING', 'ISOLATION', 'PERFORMANCE', 'SECURITY', 'OBSERVABILITY', 'COMPATIBILITY', 'RELIABILITY', 'UX', 'DATA_INTEGRITY', 'PRIVACY', 'FUNCTIONAL', 'CORRECTNESS']
                    if parts[2].upper() in categories:
                        predicates.append(parts[3])
                    else:
                        predicates.append(parts[2])

    # 2. Sectioned lists:
    # ### SAFETY
    # | ID | Predicate |
    # |---|---|
    # | SAFE-001 | Predicate text |
    # Regex for | ID | Predicate | rows
    matches = re.findall(r'\| [A-Z]{3,5}-\d+ \| (.*?) \|', content)
    predicates.extend(matches)

    # 3. Code blocks:
    # SAFETY(SAFE-001): Predicate text
    code_matches = re.findall(r'[A-Z]+\([A-Z]+-\d+\):\s*(.*?)(?:\n\s*\n|\n\s*Status:|\n\s*```|\n\s*Verified_by:)', content, re.DOTALL)
    for m in code_matches:
        predicates.append(m.strip())

    # 4. Explicit INVARIANT: / SAFETY:
    explicit_matches = re.findall(r'(?:INVARIANT|SAFETY):\s*(.*?)\n', content)
    predicates.extend(explicit_matches)

    # Clean up
    cleaned = []
    for p in predicates:
        p = p.strip().strip('`').strip('.')
        if not p: continue
        if p.lower() in ['predicate', 'category', 'id', 'short', 'predicate (short)']:
            continue
        # Ignore lines that are just "Task IDs" or similar if they leaked in
        if re.match(r'task-\d+', p.lower()): continue
        cleaned.append(p)
    return cleaned

def get_epic_name(path):
    parts = path.split(os.sep)
    if 'epics' in parts:
        idx = parts.index('epics')
        if idx + 1 < len(parts):
            # Special case for datum/epic-21
            if parts[idx+1] == 'datum' and idx + 2 < len(parts):
                return 'datum-' + parts[idx+2]
            return parts[idx+1]
    return 'root'

def main():
    epic_predicates = defaultdict(set)

    # Find all PROPERTIES.md files
    property_files = []
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file == 'PROPERTIES.md':
                property_files.append(os.path.join(root, file))

    for path in property_files:
        with open(path, 'r') as f:
            content = f.read()
            epic = get_epic_name(path)
            preds = extract_predicates(content)
            for p in preds:
                epic_predicates[p].add(epic)

    grouped_predicates = defaultdict(set)

    def normalize(p):
        p = p.lower()
        p = re.sub(r'[^a-z0-9]', ' ', p)
        p = re.sub(r'\s+', ' ', p).strip()
        return p

    for p, epics in epic_predicates.items():
        norm = normalize(p)
        if 'actor isolation' in norm:
            grouped_predicates["Actor isolation prevents races — everywhere you have actors"].update(epics)
        elif ('no transcript text' in norm or 'no meeting content' in norm) and ('telemetry' in norm or 'public' in norm):
             grouped_predicates["No meeting content in telemetry — everywhere you added observability"].update(epics)
        elif 'insert or ignore' in norm or 'never overwrites' in norm or 'upsert' in norm or 'deterministic' in norm and 'id' in norm:
            grouped_predicates["INSERT OR IGNORE / idempotent writes — everywhere DuckDB is touched"].update(epics)
        elif 'buffer only cleared on success' in norm or 'never clears the in-memory buffer' in norm or 'cleared on success' in norm or 'leaves buffer intact' in norm:
            grouped_predicates["Buffer only cleared on success — any buffered flush pattern"].update(epics)
        elif ('signatures' in norm or 'api' in norm or 'initializer' in norm) and ('unchanged' in norm or 'must remain' in norm or 'preserved' in norm):
            grouped_predicates["Existing API signatures unchanged — every refactor epic"].update(epics)
        elif 'test count' in norm or 'tests must pass' in norm or 'tests passing' in norm:
            grouped_predicates["All existing tests must pass — every PR and build"].update(epics)
        elif 'no network egress' in norm or 'never send' in norm or 'network endpoint' in norm or 'local first' in norm:
            grouped_predicates["No network egress / Local-first — all ML and storage stays on-device"].update(epics)
        elif ('privacy' in norm or 'oslog' in norm) and ('log' in norm or 'interpolation' in norm):
            grouped_predicates["Explicit OSLog privacy labels — never log user content at .public"].update(epics)
        else:
            grouped_predicates[p].update(epics)

    invariants = []
    for p, epics in grouped_predicates.items():
        if len(epics) >= 5:
            invariants.append((p, len(epics)))

    invariants.sort(key=lambda x: x[1], reverse=True)

    print("Codebase-Wide Invariants (Found in 5+ epics):")
    for p, count in invariants:
        print(f"{count}: {p}")

if __name__ == "__main__":
    main()

